endpoints.response:
event: snapshot  data: { count, tasks: Task[], timestamp }
event: diff  data: { set: Task[], remove: number[], count, timestamp }
event: prices_snapshot  data: { prices: { "56:0x...": 0.123, ... }, timestamp }
event: prices_diff  data: { set: { "56:0x...": 0.124 }, remove: ["56:0x..."], timestamp }
event: chain_data_snapshot  data: { data: ChainItem[], timestamp }
event: chain_data_diff  data: { set: ChainItem[], remove: number[], timestamp }
event: error  data: { error }
